/* ================= DATA ================= */
/* Pathways: k = colour kind; blk = chapter; steps = [title, detail] */
const PATHWAYS={
dnaRep:{t:'DNA replication',k:'gen',blk:'start',sec:'foundations',mn:'Semi-conservative: each copy keeps one old strand',steps:[
 ['Helicase unzips the double helix','Breaks hydrogen bonds at the origin to form a replication fork; topoisomerase relieves the twisting ahead of it.'],
 ['Primase lays down a short RNA primer','DNA polymerase can only add to an existing strand.'],
 ['DNA polymerase III extends the new strand 5′ → 3′','The leading strand is made continuously towards the fork.'],
 ['The lagging strand is made in Okazaki fragments','Each fragment needs its own primer.'],
 ['DNA polymerase I replaces RNA primers with DNA',''],
 ['DNA ligase seals the gaps','Result: two identical double helices, each with one old and one new strand.']],
 foot:'Drug links: fluoroquinolones block bacterial DNA gyrase (a topoisomerase); aciclovir is a false nucleotide that stops viral DNA polymerase.'},
gpcr:{t:'G protein-coupled receptor signalling (Gs)',k:'gen',blk:'start',sec:'foundations',mn:'Signal → receptor → second messenger → response',steps:[
 ['Ligand binds the receptor','For example adrenaline at a β-adrenoceptor, or PTH at the PTH receptor.'],
 ['The receptor changes shape and activates its G protein','Gα swaps GDP for GTP and separates from the βγ subunits.'],
 ['Gαs activates adenylyl cyclase',''],
 ['Adenylyl cyclase converts ATP to cAMP','The second messenger amplifies the signal many times.'],
 ['cAMP activates protein kinase A','PKA phosphorylates target proteins: the cell response.'],
 ['Switch-off','Gα hydrolyses its GTP; phosphodiesterase breaks cAMP down to AMP.']],
 foot:'Gq receptors instead activate phospholipase C → IP₃ (releases Ca²⁺ from the ER) and DAG (activates protein kinase C). Cholera toxin locks Gs permanently on.'},

intramem:{t:'Intramembranous ossification',k:'bone',blk:'msk',sec:'growth',mn:'Flat bones: skull vault, most of the clavicle',steps:[
 ['Mesenchymal cells cluster and become osteoblasts','An ossification centre forms within a fibrous membrane.'],
 ['Osteoblasts secrete osteoid, which mineralises within days','Osteoblasts trapped in the matrix become osteocytes.'],
 ['Woven bone forms as trabeculae around blood vessels','The vascular tissue between them becomes red marrow.'],
 ['Surface mesenchyme condenses into periosteum',''],
 ['Compact bone replaces woven bone at the surfaces','Spongy bone (diploë) remains in the middle, like a sandwich.']],
 foot:'Clinical: fontanelles are the gaps where skull bones have not yet met; the anterior fontanelle closes by about 18 months.'},
endochon:{t:'Endochondral ossification',k:'bone',blk:'msk',sec:'growth',mn:'Long bones: a hyaline cartilage model is replaced by bone',steps:[
 ['Mesenchyme forms a hyaline cartilage model','Covered by perichondrium.'],
 ['A bone collar forms around the diaphysis','Perichondrium becomes periosteum; chondrocytes in the centre swell and die as their matrix calcifies.'],
 ['A periosteal bud invades: the primary ossification centre','Vessels, osteoprogenitor cells and osteoclasts enter the diaphysis (fetal weeks 7–12).'],
 ['The medullary cavity forms','Osteoclasts hollow out the centre while ossification spreads towards the ends.'],
 ['Secondary ossification centres appear in the epiphyses','Mostly around and after birth.'],
 ['Cartilage remains only as articular cartilage and the growth plate','The plate fuses into the epiphyseal line after puberty.']],
 foot:'Clinical: a hand X-ray "bone age" uses which ossification centres have appeared and fused.'},
growthPlate:{t:'Growth in length at the growth plate',k:'bone',blk:'msk',sec:'growth',mn:'"Real People Have Coffee Often"',steps:[
 ['Resting (reserve) zone','Small scattered chondrocytes anchor the plate to the epiphysis.'],
 ['Proliferative zone','Chondrocytes divide and stack in columns; this pushes the epiphysis away from the shaft.'],
 ['Hypertrophic zone','Cells enlarge and mature.'],
 ['Zone of calcification','The matrix calcifies and the chondrocytes die.'],
 ['Zone of ossification','Vessels and osteoblasts invade and lay bone on the calcified cartilage scaffold.']],
 foot:'Growth hormone (through IGF-1) drives proliferation; oestrogen at the end of puberty closes the plate. Achondroplasia (activating FGFR3) slows proliferation.'},
appositional:{t:'Growth in width (appositional growth)',k:'bone',blk:'msk',sec:'growth',steps:[
 ['Periosteal osteoprogenitor cells become osteoblasts','At the outer surface of the bone.'],
 ['Osteoblasts lay ridges of bone either side of a periosteal vessel',''],
 ['The ridges fuse into a tunnel around the vessel',''],
 ['Concentric lamellae fill the tunnel inwards, forming a new osteon',''],
 ['Osteoclasts resorb bone from the inside (endosteum)','The medullary cavity widens, so the bone grows wider without becoming too heavy.']],
 foot:'Appositional growth continues throughout life, which is why acromegaly and Paget\'s disease can thicken adult bones.'},
remodel:{t:'The remodelling cycle',k:'bone',blk:'msk',sec:'remodel',mn:'"Queens Rage and Riot For More Queens"',steps:[
 ['Quiescence','The bone surface is covered by resting lining cells.'],
 ['Resorption (after activation)','Microdamage, load or PTH makes osteoblasts express RANKL; osteoclasts form, seal onto bone, secrete acid and cathepsin K and dig a pit over 2–4 weeks.'],
 ['Reversal','Osteoclasts die by apoptosis; mononuclear cells clean the pit and lay a cement line.'],
 ['Formation','Osteoblasts fill the pit with osteoid over about 3–4 months.'],
 ['Mineralisation','Hydroxyapatite is deposited; some osteoblasts are buried as osteocytes.'],
 ['Quiescence again','The remaining osteoblasts flatten into lining cells.']],
 foot:'Osteoporosis: resorption outpaces formation. Bisphosphonates and denosumab slow resorption; teriparatide boosts formation.'},
fracture:{t:'Fracture healing (secondary)',k:'bone',blk:'msk',sec:'remodel',mn:'"Here Is Holly\'s Ribena": Haematoma, Inflammation (+ soft callus), Hard callus, Remodelling',steps:[
 ['Haematoma (hours)','Torn vessels bleed and clot; bone ends die back; platelets release growth factors.'],
 ['Inflammation and granulation tissue (days)','Neutrophils then macrophages clear debris; fibroblasts and new capillaries fill the gap.'],
 ['Soft callus (about 2–3 weeks)','Chondroblasts and fibroblasts bridge the gap with fibrocartilage: "sticky" but weak.'],
 ['Hard callus (about 6–12 weeks)','Endochondral ossification turns soft callus into woven bone. Clinical union: no pain or movement at the fracture.'],
 ['Remodelling (months to years)','Woven bone becomes lamellar bone along stress lines (Wolff\'s law); excess callus is resorbed.']],
 foot:'Smoking, diabetes, steroids, infection, poor blood supply and too much movement slow healing and risk non-union.'},
lowCa:{t:'Response to low plasma calcium',k:'bone',blk:'msk',sec:'calcium',steps:[
 ['Plasma Ca²⁺ falls','Sensed by the calcium-sensing receptor (CaSR, a GPCR) on parathyroid chief cells.'],
 ['PTH secretion rises','Within minutes.'],
 ['Bone: osteoblasts make RANKL, osteoclasts resorb','Releases calcium and phosphate.'],
 ['Kidney: distal tubule reabsorbs more Ca²⁺','The proximal tubule excretes more phosphate.'],
 ['Kidney: 1α-hydroxylase switched on','Makes calcitriol.'],
 ['Calcitriol increases gut Ca²⁺ absorption','The slow arm (a day or more).'],
 ['Ca²⁺ rises; PTH switches off','Negative feedback; calcitriol also suppresses PTH.']],
 foot:'Low magnesium blocks PTH release, so hypocalcaemia will not correct until magnesium is replaced.'},
vitD:{t:'Making active vitamin D',k:'bone',blk:'msk',sec:'calcium',mn:'Skin → liver → kidney',steps:[
 ['UVB converts 7-dehydrocholesterol to cholecalciferol (D₃) in skin','Diet adds D₃ (oily fish, eggs) or D₂ (ergocalciferol).'],
 ['Liver 25-hydroxylase makes calcidiol (25-OH vitamin D)','The storage form measured in blood tests.'],
 ['Kidney 1α-hydroxylase makes calcitriol (1,25-(OH)₂ vitamin D)','Stimulated by PTH and low phosphate.'],
 ['Calcitriol binds the intracellular vitamin D receptor','Changes gene transcription (calcium channels, calbindin).'],
 ['Gut absorbs more Ca²⁺ and phosphate; bone mineralises','Calcitriol also feeds back to reduce PTH.']],
 foot:'CKD → less 1α-hydroxylase → low calcitriol → secondary hyperparathyroidism; treat with alfacalcidol. Granulomas (sarcoidosis) make calcitriol → hypercalcaemia.'},
highCa:{t:'Response to high plasma calcium',k:'bone',blk:'msk',sec:'calcium',steps:[
 ['Plasma Ca²⁺ rises','Sensed by CaSR on parathyroid chief cells and thyroid C cells.'],
 ['PTH secretion falls','Less resorption, less renal Ca²⁺ reabsorption, less calcitriol.'],
 ['Calcitonin released from C cells','Inhibits osteoclasts directly.'],
 ['Kidney excretes more Ca²⁺',''],
 ['Plasma Ca²⁺ falls back into range','']],
 foot:'Calcitonin matters little in adults: removing the thyroid does not cause hypercalcaemia. It is a tumour marker for medullary thyroid cancer.'},
nmj:{t:'Neuromuscular transmission',k:'musc',blk:'msk',sec:'muscle',steps:[
 ['An action potential reaches the motor nerve terminal',''],
 ['Voltage-gated Ca²⁺ channels open and Ca²⁺ enters','Blocked by antibodies in Lambert–Eaton syndrome.'],
 ['Vesicles fuse (SNARE proteins) and release ACh by exocytosis','Botulinum toxin cleaves SNAREs.'],
 ['ACh crosses the cleft and binds nicotinic receptors on the end plate','Ligand-gated cation channels: Na⁺ in. Blocked by antibodies in myasthenia gravis and by rocuronium.'],
 ['The end-plate potential reaches threshold','Voltage-gated Na⁺ channels fire a muscle action potential.'],
 ['Acetylcholinesterase splits ACh into acetate and choline','Choline is recycled. Inhibited by pyridostigmine and organophosphates.']]},
ecc:{t:'Excitation–contraction coupling (skeletal muscle)',k:'musc',blk:'msk',sec:'muscle',steps:[
 ['The muscle action potential spreads along the sarcolemma',''],
 ['It travels down the T-tubules into the fibre',''],
 ['Dihydropyridine receptors (voltage sensors) in the T-tubule change shape',''],
 ['They pull open ryanodine receptors on the sarcoplasmic reticulum','Ca²⁺ floods into the cytoplasm. Faulty RyR1 causes malignant hyperthermia; dantrolene blocks it.'],
 ['Ca²⁺ binds troponin C',''],
 ['Tropomyosin rolls off the myosin-binding sites on actin','Cross-bridge cycling can begin.'],
 ['Relaxation: SERCA pumps Ca²⁺ back into the SR using ATP','Tropomyosin covers the binding sites again.']]},
crossbridge:{t:'The cross-bridge cycle',k:'musc',blk:'msk',sec:'muscle',mn:'Attach, pull, release, re-cock',steps:[
 ['The myosin head (holding ADP + Pi) binds actin','Possible only once tropomyosin has moved.'],
 ['Power stroke','Release of Pi then ADP tilts the head, pulling actin towards the M line.'],
 ['ATP binds myosin and the head detaches','No ATP = no detachment: rigor mortis.'],
 ['ATP is hydrolysed to ADP + Pi','Re-cocks the head into its high-energy position.'],
 ['The cycle repeats while Ca²⁺ and ATP are present','The sarcomere shortens; filaments slide but do not shorten.']]},

erythro:{t:'Erythropoiesis',k:'blood',blk:'immune',sec:'blood',steps:[
 ['The kidney senses low oxygen delivery','Peritubular interstitial cells in the renal cortex detect hypoxia.'],
 ['Erythropoietin (EPO) is released into the blood',''],
 ['EPO stimulates erythroid progenitors in red marrow','Proerythroblast → erythroblasts, which fill with haemoglobin (needs iron, B12, folate).'],
 ['The nucleus is ejected: reticulocyte','Enters the blood and matures in 1–2 days.'],
 ['Mature red cells circulate for about 120 days','Oxygen delivery rises and EPO falls: negative feedback.'],
 ['Old red cells are removed by splenic macrophages','Haem → bilirubin; iron is recycled.']],
 foot:'Clinical: CKD causes anaemia from low EPO; living at altitude and chronic lung disease raise EPO and haemoglobin.'},
lymphFlow:{t:'The route of lymph',k:'imm',blk:'immune',sec:'lymph',mn:'Capillaries → vessels → nodes → trunks → ducts → veins',steps:[
 ['Interstitial fluid enters lymphatic capillaries','Through overlapping endothelial flaps that act as one-way valves.'],
 ['Collecting lymphatic vessels','Valved; driven by skeletal muscle and respiratory pumps.'],
 ['Lymph nodes','Filter lymph; antigen meets lymphocytes. Lymph passes through several nodes in series.'],
 ['Lymph trunks','Jugular, subclavian, bronchomediastinal, intestinal and lumbar.'],
 ['Lymph ducts','Thoracic duct (from the cisterna chyli) or right lymphatic duct.'],
 ['Venous angle','Junction of the internal jugular and subclavian veins: lymph rejoins the blood.']]},
extrav:{t:'Leukocyte extravasation',k:'imm',blk:'immune',sec:'innate',mn:'Roll, stick, squeeze, follow',steps:[
 ['Margination','Slower flow in dilated vessels pushes leukocytes to the wall.'],
 ['Rolling','Weak, reversible binding to selectins on activated endothelium.'],
 ['Activation','Chemokines (IL-8) on the endothelium switch leukocyte integrins to high affinity.'],
 ['Firm adhesion','Integrins (LFA-1) bind ICAM-1 on the endothelium; the cell stops.'],
 ['Transmigration (diapedesis)','The cell squeezes between endothelial cells using PECAM-1 and crosses the basement membrane.'],
 ['Chemotaxis','It moves up gradients of C5a, IL-8, LTB₄ and bacterial peptides.']]},
phago:{t:'Phagocytosis and the respiratory burst',k:'imm',blk:'immune',sec:'innate',steps:[
 ['Recognition and attachment','PRRs bind PAMPs; Fc and complement receptors bind microbes opsonised by IgG, C3b or CRP.'],
 ['Engulfment','Pseudopodia surround the microbe to form a phagosome.'],
 ['Phagolysosome forms','The phagosome fuses with lysosomes and granules.'],
 ['Respiratory burst','NADPH oxidase makes superoxide → hydrogen peroxide; myeloperoxidase makes hypochlorous acid (bleach).'],
 ['Killing and digestion','Reactive oxygen species, lysozyme, defensins, proteases and low pH.'],
 ['Exocytosis or presentation','Debris is expelled; macrophages and dendritic cells present peptides on MHC II.']],
 foot:'Chronic granulomatous disease: no NADPH oxidase, so no respiratory burst and recurrent S. aureus and Aspergillus infections.'},
compl:{t:'Complement activation',k:'imm',blk:'immune',sec:'innate',steps:[
 ['Trigger','Classical (C1q binds antibody on antigen), lectin (MBL binds mannose) or alternative (spontaneous C3b on a microbe).'],
 ['C3 convertase forms',''],
 ['C3 is cleaved into C3a and C3b','C3b coats the microbe (opsonin); C3a promotes inflammation.'],
 ['C5 convertase forms','C3b joins the C3 convertase.'],
 ['C5 is cleaved into C5a and C5b','C5a: chemotaxis and mast cell activation.'],
 ['C5b recruits C6, C7, C8 and C9','The membrane attack complex punches a pore: lysis.']],
 foot:'Regulators (C1 inhibitor, factor H, CD55, CD59) protect our own cells. C1-inhibitor deficiency causes hereditary angioedema.'},
thymus:{t:'T cell education in the thymus',k:'imm',blk:'immune',sec:'adaptive',steps:[
 ['Pre-T cells leave the marrow and enter the thymic cortex','Double negative: CD4⁻ CD8⁻.'],
 ['TCR genes rearrange; cells express CD4 and CD8','Double positive.'],
 ['Positive selection (cortex)','Cells that cannot bind self-MHC die by neglect: MHC restriction.'],
 ['Commitment to single positive','Binding MHC I → CD8; binding MHC II → CD4.'],
 ['Negative selection (medulla)','Cells binding self-peptide–MHC too strongly die by apoptosis; AIRE lets medullary cells display proteins from other organs.'],
 ['Naive T cells leave for blood and lymph nodes','Over 95% of thymocytes never make it.']],
 foot:'DiGeorge syndrome (22q11 deletion): no thymus, so T cell deficiency. AIRE mutations cause multi-organ autoimmunity.'},
tAct:{t:'Activating a naive T cell: three signals',k:'imm',blk:'immune',sec:'adaptive',steps:[
 ['A dendritic cell captures antigen and migrates to a lymph node','It matures on the way, raising MHC and CD80/86.'],
 ['Signal 1: TCR binds peptide–MHC','The CD4 or CD8 co-receptor stabilises binding; Ca²⁺ rises; calcineurin activates NFAT.'],
 ['Signal 2: co-stimulation','CD28 on the T cell binds CD80/86 (B7). Signal 1 without signal 2 → anergy (tolerance).'],
 ['Signal 3: cytokines decide the subset','IL-12 → Th1; IL-4 → Th2; IL-6 + TGF-β → Th17.'],
 ['IL-2 drives clonal expansion','Autocrine: thousands of identical cells within days.'],
 ['Effector and memory cells leave the node','']],
 foot:'Tacrolimus and ciclosporin block calcineurin (no IL-2). Abatacept blocks CD80/86 in rheumatoid arthritis.'},
ctl:{t:'How CD8 T cells kill',k:'imm',blk:'immune',sec:'adaptive',steps:[
 ['A naive CD8 cell is activated in a lymph node','By a dendritic cell, with help (IL-2) from Th1 cells.'],
 ['The cytotoxic T cell finds an infected cell','Its TCR recognises viral peptide on MHC I.'],
 ['A tight immunological synapse forms','Granules move towards the target.'],
 ['Perforin makes pores and granzymes enter','Granzymes trigger caspases → apoptosis.'],
 ['Or Fas ligand binds Fas on the target','A second route to apoptosis.'],
 ['The T cell detaches and kills again','Apoptosis avoids spilling cell contents and inflammation.']]},
bAct:{t:'B cell activation and antibody production',k:'imm',blk:'immune',sec:'adaptive',steps:[
 ['A naive B cell binds antigen with its BCR (surface IgM and IgD)','In a lymph node follicle.'],
 ['The B cell internalises and processes the antigen','It presents peptides on its own MHC II.'],
 ['A helper T cell, already activated by the same antigen, recognises the peptide','At the follicle border.'],
 ['T cell help: CD40L binds CD40, plus cytokines (IL-4, IL-21)',''],
 ['Germinal centre reaction','Clonal expansion, class switching (IgM → IgG, IgA or IgE) and somatic hypermutation with selection (affinity maturation).'],
 ['Plasma cells and memory B cells','Plasma cells secrete thousands of antibodies per second; memory B cells persist for years.']],
 foot:'Polysaccharide capsules can activate B cells without T cells (mostly IgM, little memory), which is why under-2s need conjugate vaccines.'},
type1:{t:'Type I hypersensitivity',k:'imm',blk:'immune',sec:'hypersens',steps:[
 ['First exposure: dendritic cells present the allergen','CD4 cells become Th2.'],
 ['Th2 cells release IL-4 and IL-13','B cells class switch to IgE.'],
 ['IgE binds FcεRI on mast cells and basophils','The person is now sensitised, with no symptoms yet.'],
 ['Re-exposure: allergen cross-links two neighbouring IgE molecules',''],
 ['Degranulation within minutes','Histamine and tryptase: vasodilation, leaky vessels, bronchoconstriction, itch.'],
 ['Late phase (hours)','Leukotrienes, prostaglandins and eosinophils sustain inflammation.']]},
anaph:{t:'Anaphylaxis: emergency treatment (RCUK)',k:'drug',blk:'immune',sec:'hypersens',mn:'Adrenaline first, adrenaline early',steps:[
 ['Recognise it','Sudden airway, breathing or circulation problems, usually with skin or mucosal changes (urticaria, angioedema).'],
 ['Call for help, remove the trigger, position','Lie flat with legs raised; sit up if breathing is difficult. Do not stand the patient up.'],
 ['IM adrenaline into the anterolateral thigh','Adults and over-12s: 500 micrograms (0.5 mL of 1 mg/mL). 6–12 years: 300 micrograms. Under 6: 150 micrograms.'],
 ['Repeat the IM dose after 5 minutes if no better',''],
 ['High-flow oxygen, IV fluid bolus, monitor',''],
 ['Refractory (no better after 2 doses): get expert help','Adrenaline infusion. Antihistamines treat skin symptoms only; steroids are not routine.'],
 ['Afterwards','Timed mast cell tryptase samples, observation, allergy clinic referral, two adrenaline auto-injectors and training.']],
 foot:'Adrenaline acts on α₁ (vasoconstriction, less oedema), β₁ (heart) and β₂ (bronchodilation, stabilises mast cells).'},
bactFight:{t:'Bacterial infection storyboard',k:'micro',blk:'immune',sec:'storyboards',steps:[
 ['Bacteria breach the epithelium and multiply',''],
 ['Tissue macrophages detect PAMPs with PRRs','They phagocytose and release IL-1, IL-6, TNF-α and chemokines (IL-8).'],
 ['Complement activates','C3b opsonises; C3a and C5a trigger mast cells.'],
 ['Mast cells degranulate','Histamine causes vasodilation and leaky vessels, so cells and proteins reach the site.'],
 ['Neutrophils arrive, drawn by C5a, IL-8 and bacterial products','They phagocytose bacteria opsonised by C3b and CRP.'],
 ['Dendritic cells carry bacteria to the lymph node','They present peptides on MHC II to naive CD4 T cells.'],
 ['Helper T cells activate B cells','Plasma cells make antibody: IgM first, then IgG.'],
 ['Antibodies neutralise toxins, opsonise and activate complement','Infection clears; memory B and T cells remain.']]},
viralFight:{t:'Viral infection storyboard',k:'micro',blk:'immune',sec:'storyboards',steps:[
 ['The virus enters cells and replicates',''],
 ['Infected cells release type I interferons (IFN-α, IFN-β)','Neighbouring cells become resistant; NK cells are activated.'],
 ['Infected cells display viral peptides on MHC I',''],
 ['NK cells kill infected cells that have lowered MHC I','Missing self.'],
 ['Dendritic cells take viral antigen to the lymph node','They present on MHC II to CD4 cells and cross-present on MHC I to CD8 cells.'],
 ['Th1 cells release IL-2 and IFN-γ','These activate CD8 T cells, NK cells and macrophages.'],
 ['Cytotoxic T cells travel to the site and kill infected cells','Perforin, granzymes and Fas ligand.'],
 ['B cells make neutralising antibodies','They block viral entry and guide NK cells (ADCC); memory forms.']]},
viralRep:{t:'Viral replication (general)',k:'micro',blk:'immune',sec:'micro',steps:[
 ['Attachment','A viral surface protein binds a specific host receptor, which decides which cells it can infect (tropism).'],
 ['Penetration','By endocytosis, or the envelope fuses with the cell membrane.'],
 ['Uncoating','The capsid breaks down and releases the genome.'],
 ['Replication and synthesis','The genome is copied and viral mRNA translated on host ribosomes (DNA viruses mostly in the nucleus, RNA viruses mostly in the cytoplasm).'],
 ['Assembly','New capsids are packaged with genomes.'],
 ['Release','Budding (enveloped viruses take host membrane) or lysis (non-enveloped viruses burst the cell).']]},
hiv:{t:'HIV (retrovirus) life cycle and drug targets',k:'micro',blk:'immune',sec:'micro',steps:[
 ['Attachment: gp120 binds CD4 and co-receptor CCR5 or CXCR4','CCR5 antagonist: maraviroc.'],
 ['Fusion: gp41 fuses the envelope with the cell membrane',''],
 ['Reverse transcription: viral RNA → DNA','Reverse transcriptase inhibitors: tenofovir, efavirenz. Error-prone, so HIV mutates fast.'],
 ['Integration into host DNA by integrase','Integrase inhibitors: dolutegravir. The provirus is permanent.'],
 ['Transcription and translation of viral polyproteins',''],
 ['Assembly and budding',''],
 ['Maturation: viral protease cuts the polyproteins','Protease inhibitors: darunavir.']]},
gram:{t:'The Gram stain',k:'micro',blk:'immune',sec:'micro',mn:'Crystal violet, Iodine, Alcohol, Safranin: "Come In And Stain"',steps:[
 ['Heat-fix a thin smear on a slide',''],
 ['Crystal violet (primary stain)','All cells turn purple.'],
 ['Gram\'s iodine (mordant)','Forms large crystal violet–iodine complexes inside cells.'],
 ['Alcohol or acetone (decolouriser)','Dissolves the Gram-negative outer membrane; the thin peptidoglycan cannot hold the complex. Thick Gram-positive peptidoglycan traps it.'],
 ['Safranin (counterstain)','Colours the decolourised Gram-negatives pink-red.'],
 ['Examine under oil immersion','Purple = Gram-positive; pink = Gram-negative. Note shape and arrangement.']]},
pathogenesis:{t:'How bacteria cause disease',k:'micro',blk:'immune',sec:'micro',mn:'Move, stick, invade, evade, damage',steps:[
 ['Transmission','Contact, droplet, airborne, faecal–oral, vector, blood, vertical; spores and biofilms survive outside the host.'],
 ['Adhesion','Adhesins and pili bind host receptors, giving host and tissue specificity.'],
 ['Invasion','Exoenzymes (hyaluronidase, collagenase) open tissue planes; some bacteria enter cells.'],
 ['Evasion','Capsules block phagocytosis and complement; IgA proteases; survival inside phagosomes (TB); antigenic variation.'],
 ['Multiplication and spread','Local, focal or systemic (bacteraemia).'],
 ['Damage','Exotoxins, endotoxin and the host\'s own inflammatory response.']]},
specimen:{t:'From specimen to sensitivities',k:'micro',blk:'immune',sec:'diagnosis',steps:[
 ['Take the right specimen before antibiotics','Aseptic technique, correct container, labelled, with clinical details; send promptly.'],
 ['Microscopy (minutes to hours)','Gram stain; cell counts (white cells in CSF or urine).'],
 ['Culture (18–48 hours)','Non-selective agar for sterile sites, selective agar for mixed-flora sites; aerobic and anaerobic.'],
 ['Identification','Colony appearance, biochemical tests, MALDI-TOF mass spectrometry.'],
 ['Sensitivity testing','Disc diffusion zones or MIC by broth dilution: sensitive, intermediate or resistant.'],
 ['Report and act','Review: narrow, switch or stop antibiotics (Start Smart then Focus).']]},
pcr:{t:'PCR (polymerase chain reaction)',k:'micro',blk:'immune',sec:'diagnosis',mn:'Denature, anneal, extend',steps:[
 ['Extract nucleic acid from the sample','For RNA viruses, reverse transcriptase first makes complementary DNA (RT-PCR).'],
 ['Denaturation at about 95 °C','The two strands separate.'],
 ['Annealing at about 50–65 °C','Short primers bind either side of the target sequence.'],
 ['Extension at about 72 °C','Heat-stable Taq polymerase copies the target.'],
 ['Repeat for 30–40 cycles','The target doubles each cycle: exponential amplification.'],
 ['Detection','Real-time fluorescent probes, or gel electrophoresis to size the product.']]},
elisa:{t:'Sandwich ELISA (detecting antigen)',k:'micro',blk:'immune',sec:'diagnosis',steps:[
 ['The well is coated with capture antibody',''],
 ['Add the patient sample','Antigen binds the capture antibody; wash.'],
 ['Add the detection antibody','It binds a second site on the antigen; wash.'],
 ['Add an enzyme-linked antibody','Or the detection antibody already carries the enzyme; wash.'],
 ['Add substrate','The enzyme turns it into a coloured product.'],
 ['Read the colour','Intensity is proportional to the amount of antigen.']],
 foot:'To detect the patient\'s antibodies instead (HIV or hepatitis serology), coat the well with antigen.'},
sepsis6:{t:'Sepsis Six (UK Sepsis Trust), within 1 hour',k:'drug',blk:'immune',sec:'ipc',steps:[
 ['Make sure a senior clinician attends',''],
 ['Give oxygen if required','Target saturations 94–98% (88–92% if at risk of CO₂ retention).'],
 ['IV access and bloods','Blood cultures, lactate, full blood count, U&E, CRP, clotting.'],
 ['Give IV antibiotics','Broad-spectrum per local guideline, after cultures but without delay.'],
 ['Give IV fluids','If hypotensive or lactate is raised.'],
 ['Monitor','NEWS2, urine output, repeat lactate.']],
 foot:'The older version is remembered as BUFALO: Blood cultures, Urine output, Fluids, Antibiotics, Lactate, Oxygen.'},
thermoCold:{t:'Response to cold',k:'gen',blk:'immune',sec:'temperature',steps:[
 ['Skin cold receptors and hypothalamic sensors detect cooling',''],
 ['The hypothalamus switches on heat-conserving responses',''],
 ['Sympathetic vasoconstriction of skin vessels','Less heat loss; piloerection.'],
 ['Shivering','Involuntary muscle contraction makes heat.'],
 ['Non-shivering thermogenesis','Brown fat (neonates); thyroid hormone and adrenaline raise metabolic rate.'],
 ['Behaviour','Add clothes, seek warmth, curl up.']],
 foot:'Response to heat: sweating, skin vasodilation and less activity.'},
fever:{t:'How fever happens',k:'imm',blk:'immune',sec:'temperature',steps:[
 ['Infection or inflammation','PAMPs such as LPS (exogenous pyrogens) activate macrophages.'],
 ['Macrophages release IL-1, IL-6 and TNF-α (endogenous pyrogens)',''],
 ['Cytokines act on the hypothalamus','Around the OVLT, where the blood–brain barrier is leaky.'],
 ['COX-2 makes prostaglandin E₂','Blocked by paracetamol, NSAIDs and aspirin.'],
 ['PGE₂ raises the hypothalamic set point',''],
 ['The body heats itself to the new set point','Vasoconstriction, shivering, chills.'],
 ['Cause removed or antipyretic given','The set point falls: sweating and vasodilation.']],
 foot:'Fever may help by slowing microbial growth and speeding immune cells. Treat for comfort rather than to normalise the number.'}
};

/* ---------- haematopoiesis tree ---------- */
const TREES={
haem:{kind:'vein',dir:'ltr',root:{t:'Haematopoietic stem cell',s:'red bone marrow',d:'Self-renewing and multipotent. Collected from blood or marrow for stem cell transplants.',c:[
  {t:'Common myeloid progenitor',s:'IL-3, GM-CSF',k:'artery',d:'Makes red cells, platelets and most innate immune cells.',c:[
    {t:'Megakaryocyte',s:'thrombopoietin',k:'artery',d:'A giant cell that sheds fragments into the blood.',c:[{t:'Platelets',s:'7–10 days',k:'artery',d:'Plug formation and clotting. No nucleus.'}]},
    {t:'Proerythroblast',s:'EPO',k:'artery',d:'Erythroblasts make haemoglobin, then eject the nucleus.',c:[{t:'Reticulocyte',s:'1–2 days in blood',k:'artery',d:'Young red cell with leftover RNA. Count rises after bleeding or haemolysis.',c:[{t:'Red blood cell',s:'120 days',k:'artery',d:'Carries oxygen. Removed by splenic macrophages.'}]}]},
    {t:'Myeloblast',s:'G-CSF',k:'artery',d:'Precursor of the granulocytes. G-CSF is given after chemotherapy to boost neutrophils.',c:[
      {t:'Neutrophil',s:'50–70% of WBC',k:'artery',d:'First responder to bacteria; phagocytosis; pus.'},
      {t:'Eosinophil',s:'1–4%',k:'artery',d:'Parasites (helminths) and late-phase allergy.'},
      {t:'Basophil',s:'<1%',k:'artery',d:'Histamine and heparin in allergy.'}]},
    {t:'Monoblast',s:'M-CSF',k:'artery',d:'Becomes the monocyte.',c:[{t:'Monocyte',s:'2–8% of WBC',k:'artery',d:'Circulates 1–3 days, then enters tissue.',c:[
      {t:'Macrophage',s:'tissue',k:'artery',d:'Phagocytosis, antigen presentation on MHC II, cytokines. Kupffer cells, alveolar macrophages, microglia; osteoclasts share this lineage.'},
      {t:'Dendritic cell',s:'tissue',k:'artery',d:'Most effective antigen-presenting cell; activates naive T cells in lymph nodes.'}]}]},
    {t:'Mast cell',s:'tissues',k:'artery',d:'Matures in tissues near vessels and mucosa; IgE-triggered degranulation.'}]},
  {t:'Common lymphoid progenitor',s:'IL-7',k:'lymph',d:'Makes all lymphocytes, adaptive and innate.',c:[
    {t:'B cell',s:'matures in marrow',k:'lymph',d:'Carries surface antibody (BCR); presents antigen on MHC II.',c:[{t:'Plasma cell',s:'antibody factory',k:'lymph',d:'Secretes antibody; long-lived plasma cells sit in marrow. Cancer of plasma cells = myeloma.'},{t:'Memory B cell',s:'years',k:'lymph',d:'Fast, high-affinity secondary response.'}]},
    {t:'T cell precursor',s:'matures in thymus',k:'lymph',d:'Positive and negative selection in the thymus.',c:[{t:'CD4 helper T cell',s:'MHC II',k:'lymph',d:'Th1, Th2, Th17, Tfh: orchestrate the response. HIV target.'},{t:'CD8 cytotoxic T cell',s:'MHC I',k:'lymph',d:'Kills virus-infected and tumour cells.'},{t:'Regulatory T cell',s:'FOXP3',k:'lymph',d:'IL-10 and TGF-β switch responses off; peripheral tolerance.'}]},
    {t:'NK cell',s:'innate lymphocyte',k:'lymph',d:'Kills cells lacking MHC I and antibody-coated cells (ADCC).'}]}]}}
};

