/* ---------- rapid recall ---------- */
const FLIPS=[
 ['msk','Normal adjusted plasma calcium','2.2–2.6 mmol/L'],
 ['msk','Which cell makes RANKL?','Osteoblasts (and osteocytes). RANKL binds RANK on osteoclast precursors; OPG is the decoy.'],
 ['msk','PTH effect on phosphate','Lowers it: less reabsorption in the proximal tubule.'],
 ['msk','Where is 1α-hydroxylase and what switches it on?','Kidney proximal tubule; PTH and low phosphate.'],
 ['msk','Bone blood tests in osteoporosis','All normal: calcium, phosphate, ALP, PTH.'],
 ['msk','DEXA T-score for osteoporosis','−2.5 or lower.'],
 ['msk','Very high ALP with normal calcium in an older man with bone pain','Paget\'s disease of bone.'],
 ['msk','"Bones, stones, groans, moans, thrones"','Hypercalcaemia.'],
 ['msk','Which band stays the same length in contraction?','The A band. I band and H zone shorten.'],
 ['msk','Calcium binds what in skeletal muscle?','Troponin C (calmodulin in smooth muscle).'],
 ['msk','Drug for malignant hyperthermia','Dantrolene (blocks the ryanodine receptor).'],
 ['msk','Antidotes for organophosphate poisoning','Atropine plus pralidoxime.'],
 ['msk','Myasthenia vs Lambert–Eaton with repeated use','Myasthenia worse; Lambert–Eaton briefly better.'],
 ['msk','Why does aspirin\'s antiplatelet effect last 7–10 days?','Irreversible COX-1 block; platelets have no nucleus to make new enzyme.'],
 ['msk','NSAID "triple whammy"','NSAID + ACE inhibitor (or ARB) + diuretic → acute kidney injury.'],
 ['msk','Bisphosphonate counselling','Empty stomach, full glass of water, stay upright 30 minutes.'],
 ['immune','Vitamin K dependent clotting factors','II, VII, IX, X ("1972"), plus proteins C and S.'],
 ['immune','PT tests which pathway, and monitors which drug?','Extrinsic and common; warfarin (as INR).'],
 ['immune','Haemophilia A','X-linked factor VIII deficiency; APTT prolonged.'],
 ['immune','Red cell lifespan','About 120 days.'],
 ['immune','Where is EPO made?','Peritubular interstitial cells of the renal cortex, in response to hypoxia.'],
 ['immune','Commonest white cell','Neutrophil (50–70%).'],
 ['immune','Only antibody to cross the placenta','IgG.'],
 ['immune','First antibody in a primary response','IgM (pentamer).'],
 ['immune','MHC class I is read by...','CD8 T cells (1 × 8 = 8).'],
 ['immune','Signal 2 for T cell activation','CD28 binding CD80/86 (B7) on the antigen-presenting cell.'],
 ['immune','Cytokine that drives Th1','IL-12.'],
 ['immune','Cytokine that makes the liver produce CRP','IL-6.'],
 ['immune','Main neutrophil chemokine','IL-8 (CXCL8).'],
 ['immune','Chemotactic complement fragment','C5a.'],
 ['immune','Membrane attack complex','C5b, C6, C7, C8, C9.'],
 ['immune','NK cells kill cells that lack...','MHC class I ("missing self").'],
 ['immune','Type IV hypersensitivity examples','Contact dermatitis, Mantoux test: T cells, 48–72 hours.'],
 ['immune','Adult IM adrenaline dose in anaphylaxis','500 micrograms (0.5 mL of 1 mg/mL), anterolateral thigh; repeat after 5 minutes.'],
 ['immune','Gram-negative bacteria stain...','Pink-red (safranin counterstain).'],
 ['immune','Endotoxin is...','Lipid A of LPS in the Gram-negative outer membrane.'],
 ['immune','Alcohol gel does not work against...','C. difficile spores and norovirus: use soap and water.'],
 ['immune','Antigenic shift','Influenza A strains swap genome segments → new subtype → pandemic.'],
 ['immune','How is MRSA resistant?','Altered penicillin-binding protein (PBP2a, mecA gene).'],
 ['immune','PCR temperatures','95 °C denature, 50–65 °C anneal, 72 °C extend.'],
 ['immune','IgM vs IgG serology','IgM = recent infection; IgG = past infection or immunity.'],
 ['immune','Fever vs hyperthermia','Fever: raised set point. Hyperthermia: normal set point, heat gain exceeds loss.'],
 ['immune','Herd immunity threshold','1 − 1/R₀ (measles: about 95%).'],
 ['immune','Lymph from the left arm drains to...','Thoracic duct → left venous angle (IJV + subclavian).']
];

/* ---------- questions ---------- */
const QUIZ=[
 {id:'m1',c:'msk',type:'sba',q:'A 72-year-old woman breaks her wrist falling from standing height. Calcium 2.40 mmol/L, phosphate 1.1 mmol/L, ALP 85 U/L, PTH normal. What is the most likely diagnosis?',o:['Osteomalacia','Osteoporosis','Paget\'s disease','Primary hyperparathyroidism','Multiple myeloma'],a:1,e:'A fragility fracture with an entirely normal bone profile is osteoporosis. Osteomalacia gives low phosphate and raised ALP and PTH; Paget\'s gives a very high ALP.'},
 {id:'m2',c:'msk',type:'sba',q:'A 68-year-old man has bone pain, increasing hat size and hearing loss. ALP is 980 U/L; calcium and phosphate are normal. What is the most likely diagnosis?',o:['Osteoporosis','Paget\'s disease of bone','Osteomalacia','Bone metastases','Osteogenesis imperfecta'],a:1,e:'Chaotic remodelling in Paget\'s disease gives a very high ALP with normal calcium. Skull enlargement compresses cranial nerves (deafness). Treated with bisphosphonates.'},
 {id:'m3',c:'msk',type:'sba',q:'A 55-year-old woman has kidney stones, constipation and low mood. Calcium 2.95 mmol/L, phosphate low, PTH raised. What is the most likely cause?',o:['Secondary hyperparathyroidism','Primary hyperparathyroidism','Vitamin D toxicity','Malignancy secreting PTH-related peptide','Hypoparathyroidism'],a:1,e:'High calcium with a high (or inappropriately normal) PTH is primary hyperparathyroidism, usually a parathyroid adenoma. In malignancy and vitamin D toxicity the high calcium suppresses PTH.'},
 {id:'m4',c:'msk',type:'sba',q:'The day after a thyroidectomy, a patient has tingling around the mouth. Inflating a blood pressure cuff causes spasm of the hand. Which sign and which abnormality?',o:['Chvostek\'s sign; hypercalcaemia','Trousseau\'s sign; hypocalcaemia','Trousseau\'s sign; hyperkalaemia','Chvostek\'s sign; hypocalcaemia','Phalen\'s sign; hypomagnesaemia'],a:1,e:'Carpal spasm with a cuff is Trousseau\'s sign of hypocalcaemia, here from parathyroid damage during surgery. Chvostek\'s is facial twitching on tapping the facial nerve.'},
 {id:'m5',c:'msk',type:'sba',q:'PTH raises plasma calcium partly by stimulating which renal enzyme?',o:['25-hydroxylase','1α-hydroxylase','24-hydroxylase','Carbonic anhydrase','Alkaline phosphatase'],a:1,e:'1α-hydroxylase in the proximal tubule converts calcidiol to calcitriol, which increases calcium absorption from the gut. 25-hydroxylation happens in the liver.'},
 {id:'m6',c:'msk',type:'sba',q:'Which cell resorbs bone, and what is its lineage?',o:['Osteoblast; mesenchymal','Osteocyte; mesenchymal','Osteoclast; monocyte–macrophage','Chondroclast; mesenchymal','Osteoprogenitor; haematopoietic'],a:2,e:'Osteoclasts are multinucleated cells of the monocyte–macrophage (haematopoietic) lineage, activated by RANKL from osteoblasts.'},
 {id:'m7',c:'msk',type:'sba',q:'During skeletal muscle contraction, which part of the sarcomere stays the same length?',o:['I band','H zone','A band','Distance between Z discs','Sarcomere length'],a:2,e:'The A band is the length of the thick (myosin) filaments, which do not change. The I band and H zone shrink as filaments slide.'},
 {id:'m8',c:'msk',type:'sba',q:'A 34-year-old woman has drooping eyelids and double vision that are worse in the evening and better after rest. What is the mechanism?',o:['Antibodies against presynaptic voltage-gated calcium channels','Antibodies against postsynaptic nicotinic ACh receptors','Cleavage of SNARE proteins','Irreversible inhibition of acetylcholinesterase','Absent dystrophin'],a:1,e:'Fatigable weakness affecting eye muscles is myasthenia gravis, a type II hypersensitivity against nicotinic receptors. Lambert–Eaton targets presynaptic calcium channels and improves with use.'},
 {id:'m9',c:'msk',type:'sba',q:'A farmer collapses with sweating, salivation, small pupils, diarrhoea and a heart rate of 42. Which drug should be given first?',o:['Pyridostigmine','Atropine','Dantrolene','Naloxone','Adrenaline'],a:1,e:'Organophosphates inhibit acetylcholinesterase, flooding muscarinic receptors (SLUDGE, bradycardia). Atropine blocks muscarinic receptors; pralidoxime can reactivate the enzyme if given early.'},
 {id:'m10',c:'msk',type:'sba',q:'A 74-year-old with knee osteoarthritis takes ramipril and furosemide. Which analgesic is most likely to cause acute kidney injury?',o:['Paracetamol','Topical ibuprofen gel','Oral naproxen','Codeine','Topical capsaicin'],a:2,e:'Oral NSAIDs block prostaglandins that keep the afferent arteriole open. With an ACE inhibitor and a diuretic this is the "triple whammy". Topical NSAIDs have little systemic absorption.'},
 {id:'m11',c:'msk',type:'sba',q:'Why does low-dose aspirin inhibit platelets for their whole lifespan?',o:['It reversibly blocks COX-2','It blocks the ADP receptor','It irreversibly acetylates COX-1 and platelets cannot make new enzyme','It increases prostacyclin from platelets','It activates antithrombin'],a:2,e:'Platelets have no nucleus, so once COX-1 is acetylated no new enzyme can be made for 7–10 days. Endothelium can make new COX, so prostacyclin recovers.'},
 {id:'m12',c:'msk',type:'sba',q:'Which advice is correct for weekly oral alendronic acid?',o:['Take with food to reduce nausea','Take at night lying down','Take on an empty stomach with a full glass of water and stay upright for 30 minutes','Take with milk to boost calcium','Crush the tablet if hard to swallow'],a:2,e:'Absorption is tiny and blocked by food and calcium; staying upright prevents oesophagitis.'},
 {id:'m13',c:'msk',type:'sba',q:'During general anaesthesia with sevoflurane, a patient develops rising end-tidal CO₂, muscle rigidity and a temperature of 40 °C. Which drug treats this?',o:['Paracetamol','Dantrolene','Suxamethonium','Neostigmine','Atropine'],a:1,e:'Malignant hyperthermia: a ryanodine receptor variant releases calcium uncontrollably. Dantrolene blocks the receptor. Suxamethonium is a trigger.'},
 {id:'m14',c:'msk',type:'sba',q:'A radius fracture is fixed with a compression plate giving absolute stability. How will it heal?',o:['Secondary healing with a large callus','Primary (direct) healing without callus','Fibrous union only','Endochondral ossification in a soft callus','It will not heal without a cast'],a:1,e:'Anatomical reduction and rigid compression allow osteons to cross the gap directly (cutting cones). Casts and nails allow micromovement, giving secondary healing with callus.'},
 {id:'m15',c:'msk',type:'sba',q:'A 25-year-old has anatomical snuffbox tenderness after a fall but a normal scaphoid X-ray. What is the best next imaging?',o:['Repeat X-ray in 6 months','MRI','DEXA scan','Ultrasound of the wrist','No imaging is needed'],a:1,e:'MRI detects occult scaphoid fractures and is recommended first-line after normal X-rays. Missed scaphoid fractures risk avascular necrosis and non-union.'},
 {id:'m16',c:'msk',type:'vsaq',q:'Which hormone, made by the parafollicular cells of the thyroid, lowers plasma calcium?',req:['calcitonin'],e:'Calcitonin inhibits osteoclasts and increases renal calcium excretion; it has a minor role in adults.'},
 {id:'m17',c:'msk',type:'vsaq',q:'In which zone of the growth plate do chondrocytes divide and form columns?',req:['prolif'],e:'The proliferative zone drives growth in length; growth hormone through IGF-1 stimulates it.'},
 {id:'m18',c:'msk',type:'vsaq',q:'Which protein in skeletal muscle binds calcium to start contraction?',req:['troponin'],e:'Ca²⁺ binds troponin C, which shifts tropomyosin off the myosin-binding sites on actin.'},
 {id:'m19',c:'msk',type:'vsaq',q:'Which form of vitamin D is measured in blood to assess vitamin D status?',req:['25|calcidiol'],e:'25-hydroxyvitamin D (calcidiol) is the storage form with a long half-life. Calcitriol is tightly regulated and does not reflect stores.'},
 {id:'m20',c:'msk',type:'vsaq',q:'A 4-year-old boy climbs up his legs to stand and has bulky calves and a very high CK. Name the disease.',req:['duchenne'],e:'Duchenne muscular dystrophy: X-linked loss of dystrophin. Gowers\' sign shows proximal weakness.'},
 {id:'m21',c:'msk',type:'vsaq',q:'Which monoclonal antibody blocks RANKL to treat osteoporosis?',req:['denosumab'],e:'Denosumab is injected every 6 months; stopping suddenly causes rebound bone loss.'},
 {id:'i1',c:'immune',type:'sba',q:'A 6-year-old boy has a swollen, painful knee after a minor fall. His maternal uncle has a similar problem. APTT is prolonged; PT and platelets are normal. What is the most likely diagnosis?',o:['Von Willebrand disease','Haemophilia A','Vitamin K deficiency','Immune thrombocytopenia','Factor V Leiden'],a:1,e:'Joint bleeds in a boy with an affected maternal relative suggest an X-linked haemophilia; A (factor VIII) is about five times commoner than B. Factor assays confirm it.'},
 {id:'i2',c:'immune',type:'sba',q:'How does warfarin work?',o:['Activates antithrombin','Directly inhibits factor Xa','Blocks vitamin K recycling so the liver makes inactive II, VII, IX and X','Irreversibly blocks platelet COX-1','Converts plasminogen to plasmin'],a:2,e:'Warfarin inhibits vitamin K epoxide reductase. It takes days to work because existing factors must clear first; it is monitored with the INR.'},
 {id:'i3',c:'immune',type:'sba',q:'Which test is used to monitor unfractionated heparin?',o:['INR','APTT','Platelet count','D-dimer','Bleeding time'],a:1,e:'Unfractionated heparin prolongs the APTT (intrinsic and common pathways). LMWH usually needs no monitoring.'},
 {id:'i4',c:'immune',type:'sba',q:'Which cell is the most effective at activating naive T cells?',o:['Neutrophil','Dendritic cell','Mast cell','Plasma cell','Eosinophil'],a:1,e:'Dendritic cells capture antigen, migrate to lymph nodes and give signal 1 (peptide–MHC) and signal 2 (CD80/86).'},
 {id:'i5',c:'immune',type:'sba',q:'A 25-year-old eats a peanut and within minutes has lip swelling, wheeze and a BP of 80/50. What should be given first?',o:['IV chlorphenamine 10 mg','IM adrenaline 500 micrograms','IV hydrocortisone 200 mg','IV adrenaline 1 mg bolus','Nebulised salbutamol'],a:1,e:'Anaphylaxis: IM adrenaline 500 micrograms into the anterolateral thigh, repeated after 5 minutes if needed. IV adrenaline boluses are for cardiac arrest or expert use only.'},
 {id:'i6',c:'immune',type:'sba',q:'Which antibody class crosses the placenta?',o:['IgA','IgD','IgE','IgG','IgM'],a:3,e:'IgG crosses via the neonatal Fc receptor (FcRn), protecting the baby for about 6 months. It also explains neonatal Graves\' and neonatal myasthenia.'},
 {id:'i7',c:'immune',type:'sba',q:'A Mantoux (tuberculin) test is read as positive at 72 hours. Which type of hypersensitivity is this?',o:['Type I','Type II','Type III','Type IV','Not a hypersensitivity reaction'],a:3,e:'Delayed (type IV) hypersensitivity: sensitised Th1 cells recruit and activate macrophages over 48–72 hours. No antibody is involved.'},
 {id:'i8',c:'immune',type:'sba',q:'A 19-year-old has had meningococcal meningitis twice. Deficiency of what is most likely?',o:['IgE','Terminal complement components (C5–C9)','Myeloperoxidase','CD8 T cells','Mannose-binding lectin only'],a:1,e:'Without the membrane attack complex, thin-walled Neisseria cannot be lysed.'},
 {id:'i9',c:'immune',type:'sba',q:'Which complement fragment is the most important chemoattractant for neutrophils?',o:['C3b','C5a','C5b','C1q','C4b'],a:1,e:'C5a is chemotactic and a potent anaphylatoxin. C3b is the main opsonin; C5b starts the membrane attack complex.'},
 {id:'i10',c:'immune',type:'sba',q:'A virus switches off MHC class I on infected cells to hide from cytotoxic T cells. Which cell is best placed to kill these cells?',o:['CD4 T cell','Natural killer cell','B cell','Eosinophil','Plasma cell'],a:1,e:'NK cells are inhibited by MHC I; when it is missing they kill ("missing self").'},
 {id:'i11',c:'immune',type:'sba',q:'A blood culture grows purple cocci in clusters that are catalase-positive and coagulase-positive. What is the organism?',o:['Streptococcus pyogenes','Staphylococcus aureus','Staphylococcus epidermidis','Neisseria meningitidis','Enterococcus faecalis'],a:1,e:'Gram-positive cocci in clusters = staphylococci; coagulase-positive = S. aureus. S. epidermidis is coagulase-negative.'},
 {id:'i12',c:'immune',type:'sba',q:'Which bacterial component triggers septic shock through TLR4?',o:['Peptidoglycan','Lipoteichoic acid','Lipopolysaccharide (lipid A)','Flagellin','Capsule polysaccharide'],a:2,e:'LPS (endotoxin) in the Gram-negative outer membrane triggers TLR4, driving TNF-α and IL-1 release, vasodilation and DIC.'},
 {id:'i13',c:'immune',type:'sba',q:'A patient develops profuse diarrhoea after a course of co-amoxiclav and is isolated. What hand hygiene should staff use after contact?',o:['Alcohol gel alone','Soap and water','Gloves alone are enough','Chlorhexidine gel','No change from usual practice'],a:1,e:'C. difficile spores resist alcohol. Wash with soap and water, use contact precautions, and clean with chlorine-based products.'},
 {id:'i14',c:'immune',type:'sba',q:'A pregnant woman\'s rubella results: IgG positive, IgM negative. What does this mean?',o:['Acute infection','Past infection or vaccination: immune','Not immune','Test failure','Congenital infection'],a:1,e:'IgG without IgM indicates past exposure or vaccination. IgM positivity suggests recent infection.'},
 {id:'i15',c:'immune',type:'sba',q:'The 2009 H1N1 influenza pandemic arose from a virus with a new combination of genome segments. What is this process called?',o:['Antigenic drift','Antigenic shift','Transduction','Conjugation','Somatic hypermutation'],a:1,e:'Antigenic shift is reassortment of segments between influenza A strains (often in pigs), producing a subtype few people are immune to.'},
 {id:'i16',c:'immune',type:'sba',q:'Which antibiotic class inhibits cell wall synthesis by binding penicillin-binding proteins?',o:['Macrolides','β-lactams','Aminoglycosides','Fluoroquinolones','Tetracyclines'],a:1,e:'β-lactams (penicillins, cephalosporins, carbapenems) block the transpeptidases that cross-link peptidoglycan.'},
 {id:'i17',c:'immune',type:'sba',q:'A 70-year-old on prednisolone is prescribed an antibiotic and develops Achilles pain. Which antibiotic is most likely responsible?',o:['Amoxicillin','Ciprofloxacin','Doxycycline','Nitrofurantoin','Clarithromycin'],a:1,e:'Fluoroquinolones cause tendinopathy and tendon rupture, especially in older people and with steroids.'},
 {id:'i18',c:'immune',type:'sba',q:'Lymph from the left arm finally drains into the blood through which structure?',o:['Right lymphatic duct','Thoracic duct','Cisterna chyli directly into the IVC','Azygos vein','Axillary vein directly'],a:1,e:'The thoracic duct drains everything except the right head, neck, arm and thorax, entering the left venous angle.'},
 {id:'i19',c:'immune',type:'sba',q:'A child with nephrotic syndrome has swollen legs and eyelids. What is the main Starling mechanism?',o:['Raised capillary hydrostatic pressure','Reduced plasma oncotic pressure','Lymphatic obstruction','Increased capillary permeability from histamine','Raised interstitial hydrostatic pressure'],a:1,e:'Albumin lost in urine lowers plasma oncotic pressure, so less fluid returns at the venous end.'},
 {id:'i20',c:'immune',type:'sba',q:'Which cytokine is the main driver of acute phase protein (CRP) production by the liver?',o:['IL-2','IL-4','IL-6','IL-10','IFN-γ'],a:2,e:'IL-6 (with IL-1 and TNF-α) drives hepatic acute phase proteins; "IL-6: aKute phase".'},
 {id:'i21',c:'immune',type:'sba',q:'Which T helper subset promotes class switching to IgE?',o:['Th1','Th2','Th17','Treg','CD8'],a:1,e:'Th2 cells make IL-4 and IL-13 (IgE class switch) and IL-5 (eosinophils): allergy and helminth defence.'},
 {id:'i22',c:'immune',type:'sba',q:'A baby in England born in 2025 attends the 1-year immunisation appointment in 2026. Which vaccines are due?',o:['6-in-1, MenB and rotavirus','MMRV, plus PCV and MenB boosters','Hib/MenC and MMR','HPV','4-in-1 pre-school booster'],a:1,e:'From January 2026, Hib/MenC is no longer given at 1 year; MMRV, PCV and MenB boosters are. The second MMRV and fourth 6-in-1 are at 18 months.'},
 {id:'i23',c:'immune',type:'sba',q:'Which test best confirms influenza from a nasopharyngeal swab within hours?',o:['Viral culture','RT-PCR','Paired serology','Gram stain','Blood culture'],a:1,e:'Influenza is an RNA virus, so reverse transcription PCR is used. Serology needs paired samples weeks apart.'},
 {id:'i24',c:'immune',type:'sba',q:'Paracetamol reduces fever mainly by which mechanism?',o:['Blocking IL-1 release','Inhibiting central COX and so PGE₂ synthesis in the hypothalamus','Causing peripheral vasoconstriction','Blocking histamine','Increasing sweating directly'],a:1,e:'Less PGE₂ lowers the raised hypothalamic set point. Antipyretics do not work in hyperthermia, where the set point is normal.'},
 {id:'i25',c:'immune',type:'sba',q:'In which phase of wound healing is type III collagen replaced by type I?',o:['Haemostasis','Inflammation','Proliferation','Remodelling','Epithelialisation'],a:3,e:'Remodelling (weeks to two years) replaces type III with type I and aligns fibres, increasing tensile strength up to about 80%.'},
 {id:'i26',c:'immune',type:'sba',q:'A 28-year-old on the combined pill has a DVT; her mother had a PE. Which inherited condition is most likely?',o:['Haemophilia B','Factor V Leiden','Von Willebrand disease','Vitamin K deficiency','Immune thrombocytopenia'],a:1,e:'Factor V Leiden makes Va resistant to activated protein C, so clotting is not switched off. It is the commonest inherited thrombophilia in Europeans.'},
 {id:'i27',c:'immune',type:'vsaq',q:'Which hormone stimulates red cell production in response to hypoxia?',req:['erythropoietin|epo'],e:'EPO from peritubular interstitial cells in the renal cortex.'},
 {id:'i28',c:'immune',type:'vsaq',q:'Which neutrophil enzyme complex generates superoxide in the respiratory burst?',req:['nadph'],e:'NADPH oxidase; its absence causes chronic granulomatous disease.'},
 {id:'i29',c:'immune',type:'vsaq',q:'Which T cell molecule provides co-stimulation by binding CD80/86?',req:['cd28'],e:'CD28 gives signal 2. Without it, signal 1 leads to anergy.'},
 {id:'i30',c:'immune',type:'vsaq',q:'Which antibody class circulates as a pentamer?',req:['igm'],e:'IgM: first in the primary response and the best activator of complement.'},
 {id:'i31',c:'immune',type:'vsaq',q:'What is the counterstain used in the Gram stain?',req:['safranin|fuchsin'],e:'Safranin (or carbol fuchsin) stains the decolourised Gram-negatives pink-red.'},
 {id:'i32',c:'immune',type:'vsaq',q:'Which antibody class binds FcεRI on mast cells?',req:['ige'],e:'IgE; cross-linking by allergen causes degranulation.'},
 {id:'i33',c:'immune',type:'vsaq',q:'Which bacterial enzyme destroys penicillins?',req:['lactamase'],e:'β-lactamase; clavulanic acid and tazobactam inhibit it.'},
 {id:'i34',c:'immune',type:'vsaq',q:'In which organ do T cells mature?',req:['thymus'],e:'Positive selection in the cortex, negative selection in the medulla.'},
 {id:'i35',c:'immune',type:'vsaq',q:'Which drug reverses unfractionated heparin?',req:['protamine'],e:'Protamine sulfate binds heparin.'},
 {id:'i36',c:'immune',type:'vsaq',q:'Which acute phase protein acts as an opsonin and is measured to monitor infection?',req:['crp|creactive'],e:'C-reactive protein rises within hours and peaks around 48 hours.'}
];
